import { css, cx } from "@styled-system/css"
import { Slot } from "radix-ui"
import type { ComponentPropsWithoutRef } from "react"
import { forwardRef } from "react"

import { ButtonVariantProps, recipe } from "./recipe"

export type ButtonProps = ComponentPropsWithoutRef<"button"> & {
  asChild?: boolean
} & ButtonVariantProps

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(
  ({ asChild, className, ...props }, ref) => {
    const Comp = asChild ? Slot.Root : "button"
    const [variantProps, componentProps] = recipe.splitVariantProps(props)
    const styles = recipe.raw(variantProps)
    return (
      <Comp
        ref={ref}
        className={cx(css(styles), className)}
        {...componentProps}
      />
    )
  },
)

Button.displayName = "Button"

import { cva, type RecipeVariantProps } from "@styled-system/css"

export type ButtonVariantProps = RecipeVariantProps<typeof recipe>

export const recipe = cva({
  base: {
    alignItems: "center",
    cursor: "pointer",
    display: "inline-flex",
    flexShrink: 0,
    gap: "1",
    justifyContent: "center",
    minH: "9",
    rounded: "md",
    textStyle: "label1",
    whiteSpace: "nowrap",
    "& svg": {
      flexShrink: 0,
    },
    _disabled: {
      cursor: "not-allowed",
      opacity: "0.5",
    },
  },
  variants: {
    size: {
      sm: {
        h: "9",
        px: "3",
        py: "1.5",
        textStyle: "label2",
      },
      md: {
        h: "10",
        px: "4",
        py: "2",
      },
      lg: {
        h: "11",
        px: "5",
        py: "2",
      },
    },
    variant: {
      destructive: {
        bg: "destructive",
        color: "destructive.foreground",
        "&:not(:disabled):hover": {
          bg: "destructive.active",
        },
      },
      link: {
        color: "foreground.primary",
        textUnderlineOffset: "2",
        "&:not(:disabled):hover": {
          textDecoration: "underline",
        },
      },
      outline: {
        bg: "layer",
        border: "base",
        color: "foreground.emphasized",
        "&:not(:disabled):hover": {
          bg: "neutral.active",
        },
      },
      primary: {
        bg: "primary",
        color: "primary.foreground",
        "&:not(:disabled):hover": {
          bg: "primary.active",
        },
      },
      secondary: {
        bg: "secondary",
        color: "secondary.foreground",
        "&:not(:disabled):hover": {
          bg: "secondary.active",
        },
      },
    },
  },
  compoundVariants: [
    {
      size: "sm",
      css: {
        "& svg": {
          height: "3.5",
          width: "3.5",
        },
      },
    },
    {
      size: "md",
      css: {
        "& svg": {
          height: "4",
          width: "4",
        },
      },
    },
    {
      size: "lg",
      css: {
        "& svg": {
          height: "5",
          width: "5",
        },
      },
    },
  ],
  defaultVariants: {
    size: "md",
    variant: "primary",
  },
})

import { cn } from "@utils/cn"
import { Slot } from "radix-ui"
import type { ComponentPropsWithoutRef } from "react"
import { forwardRef } from "react"
import type { VariantProps } from "tailwind-variants"

import { button } from "./styles"

export type ButtonVariantProps = VariantProps<typeof button>

export type ButtonProps = ComponentPropsWithoutRef<"button"> & {
  asChild?: boolean
} & ButtonVariantProps

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(
  ({ asChild, className, size, variant, ...props }, ref) => {
    const Comp = asChild ? Slot.Root : "button"

    return (
      <Comp
        ref={ref}
        className={cn(button({ size, variant }), className)}
        {...props}
      />
    )
  },
)

Button.displayName = "Button"

import { tv } from "tailwind-variants"

export const button = tv({
  base: [
    "inline-flex min-h-9 shrink-0 cursor-pointer items-center justify-center gap-1 whitespace-nowrap rounded-md",
    "typo-label1 transition-colors disabled:cursor-not-allowed disabled:opacity-50",
    "[&_svg]:shrink-0",
  ],
  variants: {
    size: {
      sm: "h-9 px-3 py-1.5 typo-label2 [&_svg]:size-3.5",
      md: "h-10 px-4 py-2 [&_svg]:size-4",
      lg: "h-11 px-5 py-2 [&_svg]:size-5",
    },
    variant: {
      destructive:
        "bg-destructive text-destructive-foreground [&:not(:disabled):hover]:bg-destructive-active",
      link: "text-foreground-primary underline-offset-2 [&:not(:disabled):hover]:underline",
      outline:
        "border border-stroke bg-layer text-foreground-emphasized [&:not(:disabled):hover]:bg-neutral-active",
      primary:
        "bg-primary text-primary-foreground [&:not(:disabled):hover]:bg-primary-active",
      secondary:
        "bg-secondary text-secondary-foreground [&:not(:disabled):hover]:bg-secondary-active",
    },
  },
  compoundVariants: [],
  defaultVariants: {
    size: "md",
    variant: "primary",
  },
})
